        {
            if (Alive(e.Lifetime, t))
                acc = Signature.Union(acc, Combination.Loop(e.Footprint, e.Loop, e.Scope));
        }
        return acc;
    }

    /// <summary>
    /// §3 / EFFECT_SCRIPT.md §3 — 端点采样审计（完备且精确，非近似；auditA 焦点1 成立）。
    /// At(t) 是分段常数函数，仅在各 Lifetime 的有限 Lo/Hi 端点跳变；故对全部有限端点采样 = 全量检查。
    /// 三道 gate（修 auditA OPEN-2/OPEN-3/OPEN-4/OPEN-5）：
    ///   (1) 守恒：脚本级时间聚合累积 net C(t)=Σ_{e.Lo≤t} Σ_{occupy c} sign(c.Mode)·scaleSize(c.Size, e.Loop)
    ///       （create/move=+，release=−；scaleSize §3.2.5，ω=⊤⇒hi=⊤）。要求全采样点 C.Hi≥0（无负陷 NegativeDip）；
    ///       在「全部事件结束后」C 区间含 0（生命周期闭合，否则 Leak）。居民层豁免（修 OPEN-4）：资源全部正向贡献仅来自 ω=⊤ 事件 ⇒ 免守恒检查（仍参与 Peak）。
    ///   (2) 峰值预算（修 OPEN-4b/OPEN-5）：At(t) 内每资源并发占用峰值 ≤ Budget.Caps[r]（NatStar.CompareToFinite）；资源不在 Caps ⇒ 不检查。
    ///   (3) 兼容（修 OPEN-3/OPEN-5）：At(t) 内按（归一化 ResourceId, ScopeId）分组的 occupy Claims 两两 Compatible.IsCompatible；冲突报 CompatibleConflict。
    /// </summary>
    public AuditResult Audit(Budget cap)
    {
        var violations = new List<Violation>();

        // 端点集合（有限 Lo/Hi；hi=⊤ 不计端点，auditA 焦点1 note）。
        var endpoints = new HashSet<ulong>();
        ulong maxFinite = 0;
        bool anyFinite = false;
        bool anyOpenEnd = false;
        foreach (var e in Events)
        {
            if (!e.Lifetime.Lo.IsTop) { endpoints.Add(e.Lifetime.Lo.Value); maxFinite = Math.Max(maxFinite, e.Lifetime.Lo.Value); anyFinite = true; }
            if (!e.Lifetime.Hi.IsTop) { endpoints.Add(e.Lifetime.Hi.Value); maxFinite = Math.Max(maxFinite, e.Lifetime.Hi.Value); anyFinite = true; }
            else anyOpenEnd = true;
        }
        var samplePoints = new List<NatStar>();
        if (anyFinite) foreach (var v in endpoints) samplePoints.Add(NatStar.Of(v));
        if (anyOpenEnd) samplePoints.Add(NatStar.Of(maxFinite + 1)); // 开放尾段的代表采样点
        if (samplePoints.Count == 0) samplePoints.Add(NatStar.Of(0)); // 空脚本/全 ⊤：采 t=0

        // 闭包采样点（全部有限事件结束后）：取最大有限端点。
        var closureT = anyFinite ? NatStar.Of(maxFinite) : NatStar.Of(0);

        // 居民层豁免预计算（修 OPEN-4 / OPEN-N1）：资源 r 的正向占用（create/move/use）仅来自 ω=⊤ 事件 ⇒ 免守恒检查（合法常驻；Use 为良性共享占用永不须 release）。
        // 两遍法（修 OPEN-N1 顺序依赖）：hasFinitePos=存在有限正向贡献；hasTopPos=存在 ω=⊤ 正向贡献。豁免 ⇔ hasTopPos && !hasFinitePos。定义顺序无关，杜绝 false-negative。
        var hasFinitePos = new HashSet<ResourceId>();
        var hasTopPos = new HashSet<ResourceId>();
        foreach (var e in Events)
            foreach (var c in e.Footprint.OccupyClaims)
                if (c.Mode is Mode.Create or Mode.Move or Mode.Use)
                {
                    var r = ResourceId.Normalize(c.Resource);
                    if (!e.Loop.Count.IsTop) hasFinitePos.Add(r);
                    else hasTopPos.Add(r);
                }
        var residentExempt = new HashSet<ResourceId>(hasTopPos.Where(r => !hasFinitePos.Contains(r)));

        // 缓存每采样点的 At(t) 与累积 net。
        var atByT = new Dictionary<ulong, Signature>();
        var cumByT = new Dictionary<ulong, Dictionary<ResourceId, SignedInterval>>();
        foreach (var t in samplePoints)
        {
            atByT[t.Value] = At(t);
            cumByT[t.Value] = CumulativeNet(t);
        }

        // gate (1) 守恒：累积 net（修 OPEN-2 时间聚合，非瞬时 IsConserved）。
        foreach (var t in samplePoints)
        {
            var cum = cumByT[t.Value];
            foreach (var kv in cum)
            {
                if (residentExempt.Contains(kv.Key)) continue;
                var c = kv.Value;
                if (!c.Hi.IsTop && c.Hi.Value < 0)
                    violations.Add(new Violation(t, kv.Key, new ScopeId.Global(), "NegativeDip",
                        $"累积净占用在 t={t} 为负（release 早于 create）：{c}"));
            }
        }
        // 闭包：全部事件结束后 C 必须含 0（生命周期闭合），否则 Leak。
        if (cumByT.TryGetValue(closureT.Value, out var closureCum))
            foreach (var kv in closureCum)
            {
                if (residentExempt.Contains(kv.Key)) continue;
                if (!kv.Value.ContainsZero)
                    violations.Add(new Violation(closureT, kv.Key, new ScopeId.Global(), "Leak",
                        $"生命周期未闭合（净效应不含 0）：{kv.Value}"));
            }

        // gate (2) 峰值预算（修 OPEN-4b）：每资源并发峰值 ≤ Caps[r]；不在 Caps ⇒ 通过。
        foreach (var t in samplePoints)
        {
            var sig = atByT[t.Value];
            foreach (var kv in cap.Caps)
            {
                var peak = PeakForResource(sig, kv.Key);
                if (peak.CompareToFinite(kv.Value) > 0)
                    violations.Add(new Violation(t, kv.Key, new ScopeId.Global(), "PeakExceeded",
                        $"峰值 {peak} > 预算 {kv.Value}"));
            }
        }

        // gate (3) 兼容（修 OPEN-3/OPEN-5）：按（归一化 ResourceId, ScopeId）分组同时存活的 occupy Claims 两两 Compatible。
        // 关键：Signature 按结构相等去重，并发同规格元素会塌缩为单 Claim ⇒ 直接遍历签名无法检测 create+create；
        // 故本 gate 遍历「同时存活的事件」展开 multiset（每个存活元素按其 ω 贡献 ω 份并发副本，§3.2.5），对组内两两 Compatible。
        foreach (var t in samplePoints)
        {
            var groups = new Dictionary<(ResourceId, ScopeId), List<Mode>>();
            foreach (var e in Events)
            {
                if (!Alive(e.Lifetime, t)) continue;
                var looped = Combination.Loop(e.Footprint, e.Loop, e.Scope).OccupyClaims;
                foreach (var c in looped)
                {
                    var key = (ResourceId.Normalize(c.Resource), c.Scope);
                    if (!groups.TryGetValue(key, out var list)) groups[key] = list = new List<Mode>();
                    var copies = e.Loop.Count.IsTop ? 2 : (int)e.Loop.Count.Value; // ω=⊤ 至少 2 份以触发配对
                    for (int k = 0; k < copies; k++) list.Add(c.Mode);
                }
            }
            foreach (var kv in groups)
                for (int i = 0; i < kv.Value.Count; i++)
                    for (int j = i + 1; j < kv.Value.Count; j++)
                        if (!Compatible.IsCompatible(kv.Value[i], kv.Value[j]))
                            violations.Add(new Violation(t, kv.Key.Item1, kv.Key.Item2, "CompatibleConflict",
                                $"{(kv.Value[i])}×{(kv.Value[j])} 冲突（CONFLICT 集，§3.2.3）"));
        }

        return new AuditResult(violations.Count == 0, violations.ToImmutableArray());
    }

    // §2.2 — Lifetime ∋ t 判定（hi=⊤ 视为无上界）。
    private static bool Alive(Interval lt, NatStar t) =>
        lt.Lo.CompareToFinite(t) <= 0 && (lt.Hi.IsTop || t.CompareToFinite(lt.Hi) <= 0);

    // §3 gate(1) — 累积有符号 net C(t) = Σ_{e.Lo≤t} Σ_{occupy c} sign(c.Mode)·scaleSize(c.Size, e.Loop)。
    private Dictionary<ResourceId, SignedInterval> CumulativeNet(NatStar t)
    {
        var dict = new Dictionary<ResourceId, SignedInterval>();
        foreach (var e in Events)
        {
            if (e.Lifetime.Lo.CompareToFinite(t) > 0) continue; // e 尚未开始（Lo≤t 才计入）
            foreach (var c in e.Footprint.OccupyClaims)
            {
                var r = ResourceId.Normalize(c.Resource);
                var scaled = ScaleSize(c.Size, e.Loop.Count);
                var contrib = c.Mode switch
                {
                    Mode.Release => new SignedInterval(Negate(scaled.Hi), Negate(scaled.Lo)), // 负向 [−hi,−lo]
                    _ => new SignedInterval(ToZ(scaled.Lo), ToZ(scaled.Hi)) // create/move 正向
                };
                dict[r] = dict.TryGetValue(r, out var cur) ? cur.Merge(contrib) : contrib;
            }
        }
        return dict;
    }

    // §3.2.5 — scaleSize：ω=⊤ ⇒ 上界开放 [lo, ⊤]；否则端点 ×ω（§3.1.5a × 律内嵌 ⊤）。
    private static Interval ScaleSize(Interval s, NatStar w)
    {
        if (w.IsTop) return new Interval(s.Lo, NatStar.Top);
        return new Interval(s.Lo * w, s.Hi * w);
    }

    private static ZStar ToZ(NatStar n) => n.IsTop ? ZStar.Top : ZStar.Of((long)n.Value);
    private static ZStar Negate(NatStar n) => n.IsTop ? ZStar.Top : ZStar.Of(-(long)n.Value);

    // §3 gate(2) — 某资源在签名内的并发峰值（occupy 桶、非 release 的 size.Hi 求和；ω 已含于 At）。
    private static NatStar PeakForResource(Signature sig, ResourceId r)
    {
        NatStar sum = NatStar.Of(0);
        foreach (var c in sig.OccupyClaims)
        {
            if (c.Mode == Mode.Release) continue;
            if (!ResourceId.Normalize(c.Resource).Equals(ResourceId.Normalize(r))) continue;
            if (c.Size.Hi.IsTop) return NatStar.Top;
            sum = sum + c.Size.Hi;
        }
        return sum;
    }
}

/// <summary>§2.3 — 峰值预算壳（软约束，非代数内核）。缺省 = 该资源无上限（⊤）。
/// 仅填关心的资源（显存 / 命令缓冲 / 通道数…）；审计时 Peak ≤ Caps[r]（NatStar.CompareToFinite），超限报 PeakExceeded。
/// 明确（修 OPEN-4）：未设 cap（默认 ⊤）= 通过；显式有限 cap = 拒绝常驻资源并发（用户主动限制，非 bug）。</summary>
public readonly record struct Budget
{
    /// <summary>§2.3 — 每资源峰值上限；缺省该资源无上限。</summary>
    public IReadOnlyDictionary<ResourceId, NatStar> Caps { get; }

    /// <summary>§2.3 — 从上限表构造。</summary>
    public Budget(IReadOnlyDictionary<ResourceId, NatStar> caps) { Caps = caps; }

    /// <summary>§2.3 — 空预算（所有资源无上限）。</summary>
    public static readonly Budget None = new(new Dictionary<ResourceId, NatStar>());
}

/// <summary>§3.2 — 审计结果。Passed=全部 gate 通过；Violations 携带反例（时刻/资源/类型/当前值 vs 上限），供 AI 直接回修 JSON。</summary>
public readonly record struct AuditResult
{
    /// <summary>§3.2 — 是否全部通过。</summary>
    public bool Passed { get; }

    /// <summary>§3.2 — 违例清单（可空）。</summary>
    public ImmutableArray<Violation> Violations { get; }

    /// <summary>§3.2 — 构造审计结果。</summary>
    public AuditResult(bool passed, ImmutableArray<Violation> violations) { Passed = passed; Violations = violations; }
}

/// <summary>§3.2 — 单条违例（反例）。携带供 AI 回修的充分信息：哪个时刻、哪个资源、哪类问题、当前值 vs 上限/阈值。</summary>
public readonly record struct Violation
{
    /// <summary>§3.2 — 违例发生的采样时刻 t。</summary>
    public NatStar AtT { get; }

    /// <summary>§3.2 — 涉事资源（归一化）。</summary>
    public ResourceId Resource { get; }

    /// <summary>§3.2 — 涉事作用域。</summary>
    public ScopeId Scope { get; }

    /// <summary>§3.2 — 违例类型：Leak | NegativeDip | PeakExceeded | CompatibleConflict。</summary>
    public string Kind { get; }

    /// <summary>§3.2 — 当前值 vs 上限/阈值（供 AI 回修 JSON）。</summary>
    public string Detail { get; }

    /// <summary>§3.2 — 构造单条违例。</summary>
    public Violation(NatStar atT, ResourceId resource, ScopeId scope, string kind, string detail)
    {
        AtT = atT;
        Resource = resource;
        Scope = scope;
        Kind = kind;
        Detail = detail;
    }
}

