[Fact]
public void At_EndpointSampling_CapturesPiecewiseConstant()
{
    var a = Ev(new Interval(NatStar.Of(0), NatStar.Of(20)), Gpu("m1"), Mode.Create, Scene("S"), Interval.Exact(1));
    var b = Ev(new Interval(NatStar.Of(10), NatStar.Of(40)), Gpu("m2"), Mode.Create, Scene("S"), Interval.Exact(1));
    var script = new EffectScript(ImmutableArray.Create(a, b));

    var endpoints = new List<ulong> { 0, 10, 20, 40 }.OrderBy(x => x).ToList();
    for (int i = 0; i < endpoints.Count - 1; i++)
    {
        var lo = endpoints[i];
        var hi = endpoints[i + 1];
        if (hi <= lo + 1) continue;
        var mid = NatStar.Of(lo + 1);
        if (mid.CompareToFinite(NatStar.Of(hi)) >= 0) continue;
        // 区间内部 At 恒定（分段常数）：mid 处 == 左端点处。
        Assert.True(SigEquals(script.At(NatStar.Of(lo)), script.At(mid)),
            $"At 在 ({lo},{hi}) 内应分段常数");
    }
}

